INSERT INTO public.recipes (
  name, slug, country, continent, is_african, category, cuisine_type, difficulty,
  servings, prep_time, cook_time, prep_time_minutes, cook_time_minutes, protein,
  summary, brief_description, history, ingredients, steps, tags, item_type
) VALUES
  ('Nordic Smoked Salmon & Cottage Cheese Bowl', 'nordic-smoked-salmon-and-cottage-cheese-bowl', 'Sweden', 'Europe', false, 'Breakfast & Brunch', 'Sweden', 'Easy', 2, 10, 0, 10, 0, 34, 'A refreshing high-protein Nordic breakfast combining high-protein curd cottage cheese with cold-smoked salmon and fresh dill.', 'A refreshing high-protein Nordic breakfast combining high-protein curd cottage cheese with cold-smoked salmon and fresh dill.', 'A refreshing high-protein Nordic breakfast combining high-protein curd cottage cheese with cold-smoked salmon and fresh dill.', '[{"name":"Cottage Cheese","amount":300,"unit":"g","notes":"Low-fat high protein","text":"300 g Cottage Cheese (Low-fat high protein)"},{"name":"Cold-Smoked Salmon","amount":150,"unit":"g","notes":"Sliced","text":"150 g Cold-Smoked Salmon (Sliced)"},{"name":"Cucumber","amount":0.5,"unit":"medium","notes":"Diced","text":"0.5 medium Cucumber (Diced)"},{"name":"Capers","amount":1,"unit":"tbsp","notes":"","text":"1 tbsp Capers"},{"name":"Fresh Dill","amount":1,"unit":"tbsp","notes":"Chopped","text":"1 tbsp Fresh Dill (Chopped)"}]'::jsonb, '["Spoon high-protein low-fat cottage cheese into serving bowls.","Arrange folded cold-smoked salmon slices alongside the cottage cheese.","Top with sliced cucumber, capers, and a generous sprinkle of fresh dill and cracked black pepper.","Serve with a slice of dark rye crispbread."]'::jsonb, ARRAY['Breakfast & Brunch', 'Sweden', 'The High Protein Cookbook', 'Easy'], 'recipe'),
  ('Moroccan Spiced Ground Beef Tagine', 'moroccan-spiced-ground-beef-tagine', 'Morocco', 'Africa', true, 'Main Courses', 'Morocco', 'Medium', 4, 15, 25, 15, 25, 37.5, 'Kefta tagine featuring spiced beef meatballs simmered in a rich tomato and bell pepper sauce, traditionally topped with poached eggs.', 'Kefta tagine featuring spiced beef meatballs simmered in a rich tomato and bell pepper sauce, traditionally topped with poached eggs.', 'Kefta tagine featuring spiced beef meatballs simmered in a rich tomato and bell pepper sauce, traditionally topped with poached eggs.', '[{"name":"Ground Beef","amount":600,"unit":"g","notes":"90% lean","text":"600 g Ground Beef (90% lean)"},{"name":"Crushed Tomatoes","amount":500,"unit":"g","notes":"","text":"500 g Crushed Tomatoes"},{"name":"Bell Pepper","amount":2,"unit":"medium","notes":"Sliced","text":"2 medium Bell Pepper (Sliced)"},{"name":"Eggs","amount":4,"unit":"large","notes":"For poaching","text":"4 large Eggs (For poaching)"},{"name":"Ground Cumin","amount":1,"unit":"tsp","notes":"","text":"1 tsp Ground Cumin"}]'::jsonb, '["Mix ground beef with cumin, paprika, coriander, minced garlic, and chopped parsley, then roll into small meatballs.","Sauté diced onions and sliced bell peppers in olive oil in a skillet, then add crushed tomatoes and spices.","Simmer meatballs in the tomato sauce for 20 minutes until cooked through.","Crack eggs directly into the sauce during the last 5 minutes, cover, and let poach."]'::jsonb, ARRAY['Main Courses', 'Morocco', 'The High Protein Cookbook', 'Medium'], 'recipe'),
  ('Greek Chicken Souvlaki Wraps', 'greek-chicken-souvlaki-wraps', 'Greece', 'Europe', false, 'Main Courses', 'Greece', 'Easy', 4, 20, 15, 20, 15, 43, 'Iconic Greek street food featuring marinated chicken skewers wrapped in flatbread with homemade tzatziki and tomatoes.', 'Iconic Greek street food featuring marinated chicken skewers wrapped in flatbread with homemade tzatziki and tomatoes.', 'Iconic Greek street food featuring marinated chicken skewers wrapped in flatbread with homemade tzatziki and tomatoes.', '[{"name":"Chicken Breast","amount":700,"unit":"g","notes":"Cubed","text":"700 g Chicken Breast (Cubed)"},{"name":"Olive Oil","amount":2,"unit":"tbsp","notes":"","text":"2 tbsp Olive Oil"},{"name":"Lemon Juice","amount":2,"unit":"tbsp","notes":"","text":"2 tbsp Lemon Juice"},{"name":"Dried Oregano","amount":2,"unit":"tsp","notes":"","text":"2 tsp Dried Oregano"},{"name":"Tzatziki Sauce","amount":0.5,"unit":"cup","notes":"","text":"0.5 cup Tzatziki Sauce"}]'::jsonb, '["Marinate cubed chicken breast in olive oil, lemon juice, garlic, oregano, salt, and pepper for 30 minutes.","Thread onto skewers and grill over high heat for 12-15 minutes until fully cooked.","Warm high-protein flatbreads or pita pockets.","Assemble wraps with chicken, sliced tomatoes, red onions, and a generous dollop of tzatziki."]'::jsonb, ARRAY['Main Courses', 'Greece', 'The High Protein Cookbook', 'Easy'], 'recipe'),
  ('Argentinian Grilled Flank Steak (Churrasco)', 'argentinian-grilled-flank-steak-churrasco', 'Argentina', 'South America', false, 'Main Courses', 'Argentina', 'Easy', 4, 15, 15, 15, 15, 48, 'Lean, nutrient-dense flank steak grilled over high heat and paired with a vibrant herbaceous chimichurri sauce.', 'Lean, nutrient-dense flank steak grilled over high heat and paired with a vibrant herbaceous chimichurri sauce.', 'Lean, nutrient-dense flank steak grilled over high heat and paired with a vibrant herbaceous chimichurri sauce.', '[{"name":"Flank Steak","amount":700,"unit":"g","notes":"Trimmed of excess fat","text":"700 g Flank Steak (Trimmed of excess fat)"},{"name":"Fresh Parsley","amount":1,"unit":"cup","notes":"Finely chopped","text":"1 cup Fresh Parsley (Finely chopped)"},{"name":"Garlic","amount":4,"unit":"cloves","notes":"Minced","text":"4 cloves Garlic (Minced)"},{"name":"Olive Oil","amount":4,"unit":"tbsp","notes":"","text":"4 tbsp Olive Oil"},{"name":"Red Wine Vinegar","amount":2,"unit":"tbsp","notes":"","text":"2 tbsp Red Wine Vinegar"}]'::jsonb, '["Season flank steak liberally with coarse sea salt and black pepper.","Grill over high heat for 4-6 minutes per side for medium-rare, ensuring a perfect sear.","Finely chop fresh parsley, cilantro, oregano, garlic, red pepper flakes, and mix with olive oil and red wine vinegar for chimichurri.","Slice steak thinly against the grain and top with chimichurri sauce."]'::jsonb, ARRAY['Main Courses', 'Argentina', 'The High Protein Cookbook', 'Easy'], 'recipe'),
  ('Thai Chicken & Basil Stir-Fry (Pad Krapow Gai)', 'thai-chicken-and-basil-stir-fry-pad-krapow-gai', 'Thailand', 'Asia', false, 'Main Courses', 'Thailand', 'Easy', 3, 10, 10, 10, 10, 40.5, 'A fiery, protein-packed street food favorite featuring minced chicken tossed with garlic, bird''s eye chilies, and holy basil.', 'A fiery, protein-packed street food favorite featuring minced chicken tossed with garlic, bird''s eye chilies, and holy basil.', 'A fiery, protein-packed street food favorite featuring minced chicken tossed with garlic, bird''s eye chilies, and holy basil.', '[{"name":"Ground Chicken","amount":600,"unit":"g","notes":"Lean breast or thigh grind","text":"600 g Ground Chicken (Lean breast or thigh grind)"},{"name":"Garlic Cloves","amount":5,"unit":"cloves","notes":"Minced","text":"5 cloves Garlic Cloves (Minced)"},{"name":"Bird''s Eye Chilies","amount":3,"unit":"whole","notes":"Sliced","text":"3 whole Bird''s Eye Chilies (Sliced)"},{"name":"Fish Sauce","amount":2,"unit":"tbsp","notes":"","text":"2 tbsp Fish Sauce"},{"name":"Fresh Holy Basil","amount":1.5,"unit":"cups","notes":"Packed leaves","text":"1.5 cups Fresh Holy Basil (Packed leaves)"}]'::jsonb, '["Mince garlic and bird''s eye chilies together in a mortar and pestle.","Heat oil in a wok and stir-fry the garlic-chili paste until aromatic.","Add ground chicken and break apart, cooking until browned.","Stir in fish sauce, soy sauce, oyster sauce, and a pinch of sugar, then toss in fresh basil leaves until wilted."]'::jsonb, ARRAY['Main Courses', 'Thailand', 'The High Protein Cookbook', 'Easy'], 'recipe')
ON CONFLICT (slug) DO NOTHING;